package org.brightstats.model;
import java.util.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.stats.*;

/** Compile explicit SEM moderation attachments to an independent product-indicator contract. */
public final class DiagramSemProducts {
    private DiagramSemProducts(){}
    public record Compiled(SemProductIndicators.Specification specification,Map<String,Integer> identities,int addedMainPaths,List<String> warnings){public Compiled{identities=Collections.unmodifiableMap(new LinkedHashMap<>(identities));warnings=List.copyOf(warnings);}}
    public static boolean requested(Document document){return document.links().stream().anyMatch(link->link.type()==ElementType.CBSEM_CONNECTION_FOR_MODERATION);}
    public static Compiled compile(Document document,List<String> columns,double[][] data,boolean means){
        if(document.family()!=Family.CBSEM||!requested(document))throw new IllegalArgumentException("Choose a covariance SEM diagram containing moderation attachments.");String method=DiagramModels.string(document.node(document.root()).properties(),"moderationMethod","MATCHED_DMC");if(!method.equals("MATCHED_DMC"))throw new IllegalArgumentException("This SEM moderation contract is MATCHED_DMC, not latent moderated maximum likelihood.");List<Link> attachments=document.links().stream().filter(link->link.type()==ElementType.CBSEM_CONNECTION_FOR_MODERATION).toList();List<DiagramModels.Term> terms=new ArrayList<>();Set<String> outcomes=new HashSet<>();for(var link:attachments){var term=DiagramModels.term(document,link,new HashSet<>());terms.add(term);outcomes.add(term.target());}
        Set<String> anchors=new HashSet<>();for(var node:document.nodes())if(node.type()==ElementType.DONGLE)anchors.add(node.id());Document base=document.remove(anchors);int added=0,serial=0;Set<String> ids=new HashSet<>();for(var node:base.nodes())ids.add(node.id());for(var link:base.links())ids.add(link.id());for(var note:base.annotations())ids.add(note.id());for(var term:terms)for(String factor:term.factors()){boolean exists=base.links().stream().anyMatch(link->(link.type().structural()||link.type().measurement()&&link.type().name().startsWith("CBSEM"))&&link.source().equals(factor)&&link.target().equals(term.target()));if(!exists){var source=base.node(factor);var target=base.node(term.target());ElementType type=source.type().latent()?target.type().latent()?ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_LV:ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV:target.type().latent()?ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV:ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_MV;String id;do{id="product_main_"+(++serial);}while(!ids.add(id));JsonObject properties=new JsonObject();properties.addProperty("free",true);properties.addProperty("value",.1);base=base.with(new Link(id,type,factor,term.target(),properties));added++;}}
        var ordinary=DiagramSem.compile(base,columns,data,means);Map<String,Integer> identities=new LinkedHashMap<>();for(var node:base.nodes())if(node.type()==ElementType.CBSEM_LATENT_VARIABLE||node.type()==ElementType.CBSEM_STANDARD_MANIFEST_VARIABLE||node.type()==ElementType.GENERIC_MANIFEST_VARIABLE)identities.put(node.id(),identities.size());List<SemProductIndicators.Interaction> interactions=new ArrayList<>();Set<Integer> involved=new HashSet<>();for(int i=0;i<attachments.size();i++){var term=terms.get(i);Integer target=identities.get(term.target());if(target==null)throw new IllegalArgumentException("A moderation outcome must be a RAM variable.");int[] factors=term.factors().stream().mapToInt(id->{Integer index=identities.get(id);if(index==null)throw new IllegalArgumentException("A moderation factor must be a RAM variable.");involved.add(index);return index;}).toArray();Arrays.sort(factors);var properties=attachments.get(i).properties();double value=properties.has("value")?DiagramModels.number(properties.get("value"),"interaction coefficient"):.1;double scale=properties.has("scale")?DiagramModels.number(properties.get("scale"),"interaction scale"):1;var coefficient=new SemProductIndicators.Coefficient(DiagramModels.bool(properties,"free",true),value,DiagramModels.string(properties,"equality",""),bound(properties,"lower"),bound(properties,"upper"),scale);String label=String.join(" x ",Arrays.stream(factors).mapToObj(ordinary.prepared().model().variables()::get).toList());interactions.add(new SemProductIndicators.Interaction(label,factors,target,coefficient));}
        Map<Integer,List<Integer>> memberships=new LinkedHashMap<>();for(var node:base.nodes())if(node.type()==ElementType.CBSEM_LATENT_VARIABLE&&involved.contains(identities.get(node.id()))){List<Integer> selected=new ArrayList<>();if(node.properties().has("productIndicators")){for(var value:node.properties().getAsJsonArray("productIndicators")){String name=value.getAsString();String id=base.nodes().stream().filter(candidate->candidate.type().observed()&&DiagramModels.string(candidate.properties(),"column","").equals(name)).map(Node::id).findFirst().orElseThrow(()->new IllegalArgumentException("Product indicator is missing from the RAM diagram: "+name));selected.add(identities.get(id));}}else{for(var link:base.links())if(link.type()==ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV&&link.source().equals(node.id())&&!outcomes.contains(link.target())){boolean pure=base.links().stream().noneMatch(other->other.target().equals(link.target())&&!other.source().equals(node.id())&&(other.type().structural()||other.type().measurement()&&other.type().name().startsWith("CBSEM")));if(pure)selected.add(identities.get(link.target()));}}memberships.put(identities.get(node.id()),selected);}
        List<PathProcess.Probe> probes=new ArrayList<>();var root=document.node(document.root()).properties();if(root.has("moderationProbes"))for(var entry:root.getAsJsonArray("moderationProbes")){var object=entry.getAsJsonObject();Map<Integer,Double> values=new LinkedHashMap<>();for(var value:object.getAsJsonObject("values").entrySet()){Integer index=identities.get(value.getKey());if(index==null)throw new IllegalArgumentException("SEM moderator probe refers to a missing variable identity.");values.put(index,DiagramModels.number(value.getValue(),"moderator probe"));}probes.add(new PathProcess.Probe(DiagramModels.string(object,"name","Probe"),values));}
        var specification=new SemProductIndicators.Specification(ordinary.prepared().model(),ordinary.prepared().columns(),interactions,memberships,probes);SemProductIndicators.prepare(data,specification);List<String> warnings=new ArrayList<>(ordinary.warnings());warnings.add("Moderation uses independent unconstrained matched product indicators with double-mean centering, not a claim of SmartPLS LMS equivalence.");if(added>0)warnings.add("Added "+added+" missing first-order main paths to preserve the interaction hierarchy. Existing fixed/free paths were retained.");return new Compiled(specification,identities,added,warnings);
    }
    private static Double bound(JsonObject properties,String name){return !properties.has(name)||properties.get(name).isJsonNull()?null:DiagramModels.number(properties.get(name),name);}
}
